using System.Text.Json;
using YoshiWorkshop;
namespace WorkshopApp;
public sealed partial class WorkshopWindow {
    public async Task RunModePreparationChecks(){
        if(!pcRoot.Contains("validation",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Copie de vérification isolée requise.");
        void Need(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        Need(SectionNames.Length==6 && SectionNames[3]=="Coopération" && SectionNames[4]=="Boss Battle","Mode sections unavailable");
        Need(ModeYoshis.Length==14 && ModeYoshis.Select(y=>y.Index).SequenceEqual(Enumerable.Range(0,14)) && ModeYoshis.All(y=>y.Name==BossBattleYoshiColors.FrenchName(y.Index)),"Atelier Yoshi names do not match native colour IDs");
        var oldSettings=new ModeSetup{Schema=1,FirstColor=1,SecondColor=6,BossYoshi=5};oldSettings.UpgradeLegacyColors();oldSettings.Validate();Need(oldSettings.Schema==2 && oldSettings.FirstColor==5 && oldSettings.SecondColor==7 && oldSettings.BossYoshi==1,"Legacy picker selections lost their Yoshi during migration");oldSettings.UpgradeLegacyColors();Need(oldSettings.FirstColor==5 && oldSettings.SecondColor==7 && oldSettings.BossYoshi==1,"Native colour migration applied twice");
        var oldBoss=new BossPreparationDocument{Schema=1,YoshiColor=7,Plan=BossBattlePlanner.Create(42,new())};oldBoss.UpgradeLegacyColors();oldBoss.Validate();Need(oldBoss.Schema==2 && oldBoss.YoshiColor==6,"Legacy black-Yoshi preparation migrated to a different colour");
        SelectPreparationSection(false);coopFirst.SelectedIndex=8;coopSecond.SelectedIndex=10;coopRespawn.Value=7;coopInteractions.Checked=true;coopLevel.SelectedItem=coopLevel.Items.Cast<CoopLevelChoice>().Single(l=>l.Key=="vanilla-43");
        var first=BuildCoopIdentity();var second=BuildCoopIdentity();Need(first==second && first.LevelSha256==second.LevelSha256,"Original snapshots depend on transient editor IDs");
        coopLocalButton.PerformClick();Need(coopLocal!=null && coopLocal.Snapshot.BothReady && coopLocal.Snapshot.Phase==CoopSessionPhase.Lobby,"Local preparation launched gameplay or lost players");Need(coopLocal!.Snapshot.Players.Select(p=>p.YoshiColor).SequenceEqual(new[]{8,10}) && first.Rules.RespawnDelayMilliseconds==7000 && first.Rules.PlayerInteractions,"Selected local rules not applied");Need(!coopSettingsPanel.Enabled && coopStopButton.Enabled,"Active preparation does not lock its settings");
        await CloseCoopResourcesAsync();RefreshCoopStatus();Need(!CoopActive && coopSettingsPanel.Enabled,"Local preparation did not release settings");
        var saved=JsonSerializer.Deserialize<ModeSetup>(File.ReadAllText(ModeSetupPath),ProjectStore.Json)!;saved.Validate();Need(saved.FirstColor==8 && saved.SecondColor==10 && saved.RespawnSeconds==7 && saved.PlayerInteractions,"Saved cooperative settings differ");
        coopInteractions.Checked=false;Need(BuildCoopIdentity().Fingerprint()!=first.Fingerprint(),"Changed rules retained same lobby identity");coopInteractions.Checked=true;
        async Task Until(Func<bool> condition){var end=DateTime.UtcNow.AddSeconds(8);while(!condition()){if(DateTime.UtcNow>=end)throw new TimeoutException("UI lobby update not received");await Task.Delay(20);}}
        await StartCoopHostAsync();var hosted=coopHost!;var guest=await CoopNetworkClient.ConnectAsync("127.0.0.1",hosted.Port,hosted.Identity,10);await guest.SetReadyAsync(true);coopReady.Checked=true;await Until(()=>coopSnapshot?.BothReady==true);Need(coopSnapshot!.Phase==CoopSessionPhase.Lobby,"Lobby UI started native game");await guest.DisposeAsync();await Until(()=>coopSnapshot?.Players[1].Connected==false && !coopReady.Checked);await StopCoopAsync();
        var identityForJoin=BuildCoopIdentity();var remote=CoopNetworkHost.Start(System.Net.IPAddress.Loopback,0,identityForJoin,8);coopJoinPort.Value=remote.Port;coopAddress.Text="127.0.0.1";await JoinCoopAsync();await remote.SetHostReadyAsync(true);coopReady.Checked=true;await Until(()=>coopSnapshot?.BothReady==true);await remote.DisposeAsync();await Until(()=>coopClient is {IsConnected:false} && !coopReady.Enabled);await StopCoopAsync();
        SelectPreparationSection(true);bossSeed.Value=42;bossYoshi.SelectedIndex=2;bossTerrain.SelectedIndex=2;GenerateBossPreview();Need(bossPlan!.Encounters.Count==10 && bossPlan.Encounters[0].Family==BossBattleFamily.YellowCandy && !bossPlan.Encounters[0].GenieCompanion && bossPlan.Encounters[^1].Family==BossBattleFamily.RedCandyFinal,"Boss order differs");Need(bossPlan.Encounters.Take(6).Select(e=>e.Family).Distinct().Count()==6,"Required family missing");bossSave.PerformClick();var document=JsonSerializer.Deserialize<BossPreparationDocument>(File.ReadAllText(BossPlanPath),BossBattleJson.Options)!;document.Validate();Need(document.YoshiColor==2 && document.Plan.Fingerprint()==bossPlan.Fingerprint(),"Boss plan or Yoshi lost on save");Need(BossBattleAdmission.Missing(document.Plan,new()).Count>0,"Unimplemented native battle became playable");
        string fingerprint=bossPlan.Fingerprint();bossSeed.Value=43;GenerateBossPreview();Need(bossPlan.Fingerprint()!=fingerprint,"New seed did not create new plan");bossSeed.Value=42;GenerateBossPreview();Need(bossPlan.Fingerprint()==fingerprint,"Same seed failed reproducibility");
        Need(bossPreview.Columns.Count==2 && bossPreview.Rows.Count==10,"Upcoming encounter metadata exposed as columns");
        string beforeMask=bossPlan.Fingerprint();foreach(DataGridViewRow row in bossPreview.Rows){Need((string)row.Cells[1].Value=="À découvrir","Upcoming boss label exposed");bossPreview.CurrentCell=row.Cells[0];ShowBossEncounter();Need(!BossBattleCatalog.Families.Any(f=>bossDescription.Text.Contains(f.Label,StringComparison.OrdinalIgnoreCase)),"Upcoming boss exposed through selected-row details");}
        Need(bossPlan.Fingerprint()==beforeMask,"Masking changed the prepared encounter plan");
        Directory.CreateDirectory(Path.Combine(pcRoot,"build/modes-0221"));SelectPreparationSection(false);PerformLayout();RenderPreview(Path.Combine(pcRoot,"build/modes-0221/coop-preparation.png"));SelectPreparationSection(true);PerformLayout();RenderPreview(Path.Combine(pcRoot,"build/modes-0221/boss-preparation.png"));
        File.WriteAllText(Path.Combine(pcRoot,"build/modes-0221/ui-modes.json"),JsonSerializer.Serialize(new{sixSections=true,bossFutureNamesHidden=true,bossSelectionKeepsMystery=true,maskingPreservesPlan=true,uiHostAndJoinLoopback=true,peerDepartureReflected=true,disconnectedClientReadyDisabled=true,localTwoPlayersPrepared=true,noNativeGameplayStarted=true,settingsLockedAndReleased=true,cooperativeRulesPersisted=true,levelFingerprintStable=true,rulesChangeFingerprint=true,bossTenFights=true,requiredFamilies=true,firstCandyAlwaysSolo=true,redFinal=true,bossPlanSaveReload=true,seedReproducible=true,nativeAdmissionBlocked=true,personalProgressUsed=false},ProjectStore.Json));
    }
}
